# Break My Fix finding 1, generated by Tracefix: slugify returns a wrong value.
# Property (issue): The slug never starts or ends with a dash, whatever punctuation or whitespace the title starts or ends with.
# Quote: Slugs for titles ending in punctuation get a trailing dash
# Run it with pytest: it fails for as long as the code breaks this property.

from blog.slug import slugify


def test_break_my_fix_1() -> None:
    title = '-'
    result = slugify(title=title)
    assert (not result.startswith('-') and not result.endswith('-'))
